/**
 * Built-in UI icon set: inline SVG strings, one per icon name, grouped
 * by the feature that renders them so bundlers ship only the groups a
 * consumer's plugins import. Pure string data — safe in this DOM-free
 * package. Runtimes render these when the consumer supplies no custom
 * icon for a name.
 *
 * The artwork is lightGallery's own icon set, carried over from the
 * 2.x icon font: each glyph's vector outline extracted from the font
 * and re-baselined onto a square viewBox (font ascent 960 on a 1024
 * em). Same shapes the library has always shipped — now crisp inline
 * SVGs that follow `currentColor`.
 */

/** The icon-name contract shared by every runtime and plugin. */
export type LgIconName =
    | 'close'
    | 'prev'
    | 'next'
    | 'download'
    | 'maximize'
    | 'minimize'
    | 'more'
    | 'zoomIn'
    | 'zoomOut'
    | 'actualSize'
    | 'rotateLeft'
    | 'rotateRight'
    | 'flipHorizontal'
    | 'flipVertical'
    | 'share'
    | 'shareFacebook'
    | 'shareX'
    | 'sharePinterest'
    | 'autoplayPlay'
    | 'autoplayPause'
    | 'fullscreen'
    | 'fullscreenExit'
    | 'comment'
    | 'commentClose'
    | 'toggleThumbnails';

